'use client';

import { motion, MotionStyle, Transition } from 'motion/react';

import { cn } from '@/lib/utils';

type BeamBorderProps = {
  size?: number;
  duration?: number;
  delay?: number;
  colorFrom?: string;
  colorTo?: string;
  transition?: Transition;
  className?: string;
  style?: React.CSSProperties;
  reverse?: boolean;
  initialOffset?: number;
  borderWidth?: number;
  double?: boolean;
};

function BeamBorder({
  className,
  size = 100,
  delay = 0,
  duration = 6,
  colorFrom = '#ffaa40',
  colorTo = '#9c40ff',
  transition,
  style,
  reverse = false,
  initialOffset = 0,
  borderWidth = 1,
  double = true
}: BeamBorderProps) {
  return (
    <div
      className="pointer-events-none absolute inset-0 rounded-[inherit] border-(length:--border-beam-width) border-transparent mask-[linear-gradient(transparent,transparent),linear-gradient(#000,#000)] mask-intersect [mask-clip:padding-box,border-box]"
      style={
        {
          '--border-beam-width': `${borderWidth}px`
        } as React.CSSProperties
      }
    >
      <motion.div
        className={cn(
          'absolute aspect-square',
          reverse
            ? 'bg-linear-to-l from-transparent via-(--color-to) to-(--color-from)'
            : 'bg-linear-to-l from-(--color-from) via-(--color-to) to-transparent',
          className
        )}
        style={
          {
            width: size,
            offsetPath: `rect(0 auto auto 0 round ${size}px)`,
            '--color-from': colorFrom,
            '--color-to': colorTo,
            ...style
          } as MotionStyle
        }
        initial={{ offsetDistance: `${initialOffset}%` }}
        animate={{
          offsetDistance: reverse
            ? [`${100 - initialOffset}%`, `${-initialOffset}%`]
            : [`${initialOffset}%`, `${100 + initialOffset}%`]
        }}
        transition={{
          repeat: Infinity,
          ease: 'linear',
          duration,
          delay: -delay,
          ...transition
        }}
      />
      {double && (
        <motion.div
          className={cn(
            'absolute aspect-square',
            reverse
              ? 'bg-linear-to-l from-transparent via-(--color-to) to-(--color-from)'
              : 'bg-linear-to-l from-(--color-from) via-(--color-to) to-transparent',
            className
          )}
          style={
            {
              width: size,
              offsetPath: `rect(0 auto auto 0 round ${size}px)`,
              '--color-from': colorFrom,
              '--color-to': colorTo,
              ...style
            } as MotionStyle
          }
          initial={{ offsetDistance: `${50 + initialOffset}%` }}
          animate={{
            offsetDistance: reverse
              ? [`${100 - (50 + initialOffset)}%`, `${-(50 + initialOffset)}%`]
              : [`${50 + initialOffset}%`, `${100 + (50 + initialOffset)}%`]
          }}
          transition={{
            repeat: Infinity,
            ease: 'linear',
            duration,
            delay: -delay,
            ...transition
          }}
        />
      )}
    </div>
  );
}
export { BeamBorder, type BeamBorderProps };
